from django.conf import settings
from django.db import migrations

ROLE_NAMES = {'pet owner', 'medical provider', 'admin'}


def copy_roles_to_profiles(apps, schema_editor):
    Account = apps.get_model(settings.AUTH_USER_MODEL)
    Profile = apps.get_model('vert_core', 'Profile')
    Record = apps.get_model('vert_core', 'User')
    for account in Account.objects.all():
        text = (Record.objects.filter(user=account).exclude(user_permissions='').order_by('id').values_list('user_permissions', flat=True).first())
        role = (text or '').strip().lower()
        if role not in ROLE_NAMES:
            role = ''
        Profile.objects.get_or_create(user=account, defaults={'role': role})


def copy_roles_back(apps, schema_editor):
    Profile = apps.get_model('vert_core', 'Profile')
    Record = apps.get_model('vert_core', 'User')
    for profile in Profile.objects.exclude(role=''):
        record = Record.objects.filter(user_id=profile.user_id).order_by('id').first()
        if record:
            record.user_permissions = profile.role
            record.save(update_fields=['user_permissions'])


